# ── Reading 7 preflight: the live cap proof runs at the RUN STATE'S cap ────────────────────────
# It sent nine requests and expected `[200]*8 + [429]`, which proves the cap only when the cap is
# 8 -- so the manifest's own live cap proof could not run on a profile setting 24, and that was the
# profile a reading was about to use. The cap became one number carried by the run state in
# E.CB2-N; this was the last consumer that had not been told.
new('net/captest_client.py', '"""CAP+1 minimal chat completions through the cap-test proxy; prints only status codes.\n\nThe count and the expectation both come from the RUN STATE\'S CAP, not from a literal. They used to\nbe nine requests and `[200]*8 + [429]`, which proves the cap only when the cap is 8 -- so the live\ncap proof could not run on a profile that sets 24, and the one profile it could not run on was the\none a reading was about to use. The cap became one number carried by the run state (E.CB2-N); this\nis the last consumer that had not been told.\n"""\nimport json, os, sys, urllib.error, urllib.request\n\nCAP = int(os.environ.get("CB2_CAP", "8"))\nbody = json.dumps({"model": os.environ.get("CB2_MODEL", "qwen3.8:27b-q4_K_M"), "messages": [{"role": "user", "content": "Reply with the single word READY."}], "max_tokens": 4}).encode()\ncodes = []\nfor _ in range(CAP + 1):\n    req = urllib.request.Request("http://172.30.0.8:8080/v1/chat/completions", data=body, headers={"Content-Type": "application/json"})\n    try:\n        r = urllib.request.urlopen(req, timeout=180)\n        r.read(); codes.append(r.status)\n    except urllib.error.HTTPError as e:\n        codes.append(e.code)\n    except Exception:\n        codes.append(0)\nprint("status codes:", codes)\n# The cap holds BEFORE the model: exactly CAP accepted, then a refusal.\nsys.exit(0 if codes == [200] * CAP + [429] else 1)\n')
rw('net/captest.sh', [
    ('# Live proof of the hard cap: a throwaway proxy at CAP=8 and a plain client on cb2net sending\n# nine minimal chat completions. Expected receipt: accepted 8 / refused 1 / attempted 9,\n# upstream_errors 0, tls_hostname_verified true. Counts only. Exit non-zero otherwise.\nset -u\nFIX="$(cd "$(dirname "$0")/.." && pwd)"; CD=$(mktemp -d /tmp/cb2-captest-XXXX); . "$FIX/run/profile.sh"; cb2_profile_load "$FIX" || exit 1\ntrap \'bash "$FIX/run/proxy.sh" down cb2proxy-captest >/dev/null 2>&1; docker rm -f cb2-captest-client >/dev/null 2>&1; rm -rf "$CD"\' EXIT\nbash "$FIX/run/proxy.sh" up cb2proxy-captest "$CD" 172.30.0.8 >/dev/null || { echo "proxy not ready"; exit 1; }\ndocker run --rm --name cb2-captest-client --network cb2net --dns 127.0.0.1 -e CB2_MODEL="$CB2_MODEL" -v "$FIX/net/captest_client.py:/c.py:ro" python:3.13-slim python3 /c.py 2>/dev/null || { echo "client statuses were not exactly eight 200s then a 429"; exit 1; }\npython3 - "$CD/requests.json" <<\'EOF\'\nimport json, sys\nd = json.load(open(sys.argv[1]))\nacc, ref, upe, tls = d["model_requests"], d["refused_over_cap"], d["upstream_errors"], d.get("tls_hostname_verified")\nprint(f"cap test receipt [{d.get(\'profile\')} -> {d.get(\'upstream\')} models {d.get(\'response_models\')}]: accepted {acc} / refused {ref} / attempted {acc + ref} / upstream_errors {upe} / tls {tls}")\nsys.exit(0 if (acc, ref, upe, tls) == (8, 1, 0, True) else 1)\nEOF\n',
     '# Live proof of the hard cap: a throwaway proxy at the RUN STATE\'S CAP and a plain client on\n# cb2net sending cap+1 minimal chat completions. Expected receipt: accepted <cap> / refused 1 /\n# attempted cap+1, upstream_errors 0, tls_hostname_verified true. Counts only, exit non-zero\n# otherwise. The cap was a literal 8 here, so this proof could not run on a profile setting 24 --\n# and that was the profile a reading was about to use.\nset -u\nFIX="$(cd "$(dirname "$0")/.." && pwd)"; CD=$(mktemp -d /tmp/cb2-captest-XXXX); . "$FIX/run/profile.sh"; cb2_profile_load "$FIX" || exit 1\ntrap \'bash "$FIX/run/proxy.sh" down cb2proxy-captest >/dev/null 2>&1; docker rm -f cb2-captest-client >/dev/null 2>&1; rm -rf "$CD"\' EXIT\nbash "$FIX/run/proxy.sh" up cb2proxy-captest "$CD" 172.30.0.8 >/dev/null || { echo "proxy not ready"; exit 1; }\ndocker run --rm --name cb2-captest-client --network cb2net --dns 127.0.0.1 -e CB2_MODEL="$CB2_MODEL" -e CB2_CAP="$CB2_CAP" -v "$FIX/net/captest_client.py:/c.py:ro" python:3.13-slim python3 /c.py 2>/dev/null || { echo "client statuses were not exactly $CB2_CAP 200s then a 429"; exit 1; }\npython3 - "$CD/requests.json" <<\'EOF\'\nimport json, sys\nd = json.load(open(sys.argv[1]))\nacc, ref, upe, tls = d["model_requests"], d["refused_over_cap"], d["upstream_errors"], d.get("tls_hostname_verified")\nprint(f"cap test receipt [{d.get(\'profile\')} -> {d.get(\'upstream\')} models {d.get(\'response_models\')}]: accepted {acc} / refused {ref} / attempted {acc + ref} / upstream_errors {upe} / tls {tls}")\nimport os\nsys.exit(0 if (acc, ref, upe, tls) == (int(os.environ[\'CB2_CAP\']), 1, 0, True) else 1)\nEOF\n'),
])
